import{_ as o,l as n,o as e,c as s,v as t,p as l,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"事件响应","description":"","frontmatter":{"title":"事件响应","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/incident-response.md","filePath":"cs/incident-response.md","lastUpdated":1789023840000}'),c={name:"cs/incident-response.md"};function m(_,a,E,A,T,u){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="事件响应" tabindex="-1">事件响应 <a class="header-anchor" href="#事件响应" aria-label="Permalink to &quot;事件响应&quot;">​</a></h1><div class="epigraph"><p>事件响应是预先写好的状态机：准备、检测、遏制、根除、恢复、复盘。临时发挥会破坏证据并扩大范围。目标是把事故从灾难收成可管理的窗口。</p><footer>—— NIST SP 800-61；对照 Anderson 对事故</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/siem-logging">SIEM</a>告警。缺口是<strong>人与流程接到告警之后</strong>。本课讲生命周期与证据保全，不写攻击者手册。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>告警不等于已定性。先隔离再取证，或先取证再隔离，取决于传播速度。缺口是角色、沟通、法律保留。</p><h3 id="遏制不等于关机" tabindex="-1">遏制不等于关机 <a class="header-anchor" href="#遏制不等于关机" aria-label="Permalink to &quot;遏制不等于关机&quot;">​</a></h3><p>关机丢易失证据。网卡隔离、凭证轮换常更准。</p><p><span class="marginnote">SP 800-61。禁止报复性黑客。ATT&amp;CK 下一课给对手行为共同语言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>六阶段。桌面推演。下一课 ATT&amp;CK 矩阵作检测覆盖图。</p>',12)),(e(),l(h,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREP%5B%22%E5%87%86%E5%A4%87%22%5D%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20CON%5B%22%E9%81%8F%E5%88%B6%22%5D%0A%20%20CON%20--%3E%20ERAD%5B%22%E6%A0%B9%E9%99%A4%E4%B8%8E%E6%81%A2%E5%A4%8D%22%5D%0A%20%20ERAD%20--%3E%20LES%5B%22%E5%A4%8D%E7%9B%98%E6%94%B9%E5%9F%BA%E7%BA%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>响应把纵深从技术接到组织。ATT&amp;CK 下一课把对手技术分类，便于问「我们能看见哪一步」。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写攻击复现。ATT&amp;CK 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>日志之后要状态机，不要临时发挥。</li><li>遏制与取证权衡要预先写。</li><li>复盘必须改基线，否则只演戏。</li><li>下一课 ATT&amp;CK。</li><li>出处：NIST SP 800-61；Anderson。</li></ul>',8))])}const B=o(c,[["render",m]]);export{P as __pageData,B as default};
